tasks = {"A": (3, [], 0), "B": (2, ["A"], 0), "C": (4, ["A"], 0),
         "D": (5, ["B"], 1), "E": (1, ["C", "D"], 0), "F": (2, ["C"], 0),
         "G": (1, ["E", "F"], 0)}
finish = {}
def done(t):
    if t not in finish:
        dur, pre, lag = tasks[t]
        start = max([done(p) for p in pre], default=0) + lag
        finish[t] = start + dur
    return finish[t]
