from itertools import combinations
T = {"A": (6, ""), "B": (5, ""), "C": (4, "A"), "D": (3, "AB"), "E": (4, "B"),
     "F": (5, "CD"), "G": (4, "E"), "H": (3, "FG"), "I": (3, "D")}
WORKERS = 2
best = [10**9]
def search(t, done, running):
    if len(done) == len(T):
        best[0] = min(best[0], t)
        return
    busy = {k for _, k in running}
    ready = [k for k in T if k not in done and k not in busy and set(T[k][1]) <= done]
    free = WORKERS - len(running)
    for r in range(min(free, len(ready)), -1, -1):
        for start in combinations(ready, r):
            run = sorted(running + [(t + T[k][0], k) for k in start])
            if not run:
                continue
            nt = run[0][0]
            search(nt, done | {k for f, k in run if f == nt}, [e for e in run if e[0] != nt])
search(0, frozenset(), [])
print(best[0])

