from fractions import Fraction as F
def plan(name, i, o):
    if name == "X":
        return F(30, 100) * i + F(120, 100) * o
    if name == "Y":
        return 15 + F(25, 100) * max(0, i - 30) + 1 * max(0, o - 3)
    return F(40)
best = None
for name in "XYZ":
    for li in range(0, 41):
        for lo in range(0, 7):
            if li + lo > 20:
                continue
            cost = plan(name, 40 - li, 6 - lo) + F(4, 100) * (li + lo)
            best = cost if best is None else min(best, cost)
print(f"{float(best):.2f}")

seq = "A B C A B D A C B A D C".split()
CAP = 2
states = {frozenset(): 0}
for m in seq:
    nxt = {}
    for s, loads in states.items():
        if m in s:
            options = [(s, loads)]
        elif len(s) < CAP:
            options = [(s | {m}, loads + 1)]
        else:
            options = [((s - {e}) | {m}, loads + 1) for e in s]
