from itertools import product
sizes = [600, 600, 600, 420, 420, 300, 50]
CAP = 1000
def fits(k):
    for asg in product(range(k), repeat=len(sizes)):
        load = [0] * k
        for s, d in zip(sizes, asg):
            load[d] += s
        if max(load) <= CAP:
            return True
    return False
k = 1
while not fits(k):
